<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Create\TrustedClientCreateAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Update\TrustedClientUpdateAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\List\TrustedClientListAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Retrieve\TrustedClientRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Delete\TrustedClientDeleteAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Enable\TrustedClientEnableAllowDecision;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Disable\TrustedClientDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlyForRootAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(TrustedClientCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientCreateAllowDecision', $proposal);
    }
    public function checkUpdate(TrustedClientUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientUpdateAllowDecision', $proposal);
    }
    public function checkList(TrustedClientListAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientListAllowDecision', $proposal);
    }
    public function checkRetrieve(TrustedClientRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientRetrieveAllowDecision', $proposal);
    }
    public function checkDelete(TrustedClientDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientDeleteAllowDecision', $proposal);
    }
    public function checkEnable(TrustedClientEnableAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientEnableAllowDecision', $proposal);
    }
    public function checkDisable(TrustedClientDisableAllowDecision $proposal): AllowDecision
    {
        return $this->check('TrustedClientDisableAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on OnlyForRootAllow Trusted client");
        $span = $this->startSpan("Check " . $name . " on OnlyForRootAllow Trusted client");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!(($identity->hasScope("platform:global_access") && $identity->hasRole("admin")))) {
                    $proposal->deny('Disabled if not OnlyForRoot');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
